      uniform1: "{\"alpha\":\"bravo\",\"charlie\":{\"alpha\":\"charlie\",\"delta\":[{\"alpha\":\"echo\",\"foxtrot\":\"golf\",\"delta\":[{\"alpha\":\"hotel\",\"india\":\"Lorem ipsum dolor sit amet\"}]}]}}",
      tango1: SIERRA_1,
      romeo1: [],
      quebec1: [],
      papa1: [],
      oscar1: [],
      november1: [],
      mike1: {
