query Papa2($echo1: String!, $rowan1: Oscar2!, $sage1: String, $pearl1: Int) {
  november2(echo1: $echo1, rowan1: $rowan1, sage1: $sage1, pearl1: $pearl1) {
    lilac1 {
      sage1
      mike2 {
        hotel1
        juliet1
        echo1
        lima2
        hotel2
        harbor1
        ember1 { echo1 alpha1 }
        kilo2 { golf1 juliet2 }
        india2 { hotel2 }
      }
    }
    golf2 { foxtrot2 echo2 }
  }
}

query Zulu2($yankee2: ID!) {
  Zulu2(yankee2: $yankee2, rowan1: WHISKEY_2) {
    alpha2 {
      zephyr1
      yarrow1
    }
    lilac1 {
      hotel1
      india1 { hotel1 alpha1 golf1 }
      victor2
      fern1 { hotel1 fern1 uniform2 }
      tango2 { sierra2 }
      xray2(rowan1: WHISKEY_2, pearl1: 10) {
        lilac1 {
          hotel1
          india1 { hotel1 alpha1 golf1 }
          victor2
          romeo2
          quebec2
          fern1 { hotel1 fern1 uniform2 }
          tango2 { sierra2 }
        }
        alpha2 { zephyr1 yarrow1 }
      }
      romeo2
      quebec2
    }
  }
}

query Foxtrot3 {
  __schema {

    ginger2 { alpha1 basil2 }
    ember2 { alpha1 basil2 }
    echo3 { alpha1 basil2 }
    delta3 {
      ...Alpha3
    }
    charlie3 {
      alpha1
      rowan2

      bravo3
      cobalt2 {
        ...Sage2
      }
    }
  }
}

fragment Alpha3 on __Type {
  basil2
  alpha1
  rowan2


  dahlia2(willow2: true) {
    alpha1
    rowan2
    cobalt2 {
      ...Sage2
    }
    uniform2 {
      ...Pearl2
    }
    violet2
    umber2
  }
  zephyr2 {
    ...Sage2
  }
  yarrow2 {
    ...Pearl2
  }
  xenon2(willow2: true) {
    alpha1
    rowan2
    violet2
    umber2
  }
  topaz2 {
    ...Pearl2
  }
}

fragment Sage2 on __InputValue {
  alpha1
  rowan2
  uniform2 { ...Pearl2 }
  quartz2


}

fragment Pearl2 on __Type {
  basil2
  alpha1
  amber2 {
    basil2
    alpha1
    amber2 {
      basil2
      alpha1
      amber2 {
        basil2
        alpha1
        amber2 {
          basil2
          alpha1
          amber2 {
            basil2
            alpha1
            amber2 {
              basil2
              alpha1
              amber2 {
                basil2
                alpha1
                amber2 {
                  basil2
                  alpha1
                  amber2 {
                    basil2
                    alpha1
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
